private.reference_solution:
#include <bitset>
#include <iostream>
#include <string>

int main() {
    std::string line;
    if (!std::getline(std::cin, line)) return 1;
    if (line.size() < 1 || line.size() > 64) return 1;
    for (char ch : line) {
        if (ch != '0' && ch != '1') return 1;
    }
    std::bitset<64> bits(line);
    std::cout << bits.count() << std::endl;
    return 0;
}

