private.reference_solution:
#include <iostream>
#include <string>
#include <vector>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 1 || n > 1000) return 1;
    std::vector<long long> values;
    std::string kind;
    for (int i = 0; i < n; i++) {
        if (!(std::cin >> kind)) return 1;
        if (kind == "push") {
            long long x = 0;
            if (!(std::cin >> x)) return 1;
            if (x < 0 || x > 1000) return 1;
            values.push_back(x);
        } else if (kind == "min") {
            if (values.empty()) {
                std::cout << "empty" << std::endl;
            } else {
                long long best = values[0];
                for (long long value : values) {
                    if (value < best) best = value;
                }
                std::cout << best << std::endl;
            }
        } else if (kind == "size") {
            std::cout << values.size() << std::endl;
        } else {
            return 1;
        }
    }
    return 0;
}
